func (q *Queries) LockStudyCircleForMemberLimit(ctx context.Context, id int64) (int64, error) {
	row := q.db.QueryRow(ctx, lockStudyCircleForMemberLimit, id)
	var max_members int64
	err := row.Scan(&max_members)
	return max_members, err
}

